import{z as o,x as s,o as t,c as d,q as A,j as i,D as e,d as r,s as n,S as B,b as a}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"REINFORCE 与方差","description":"","frontmatter":{"title":"REINFORCE 与方差","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/reinforce-variance.md","filePath":"llm/reinforce-variance.md","lastUpdated":1791413859000}'),p={name:"llm/reinforce-variance.md"};function m(_,E,C,h,c,f){const l=s("Mermaid");return t(),d("div",null,[E[2]||(E[2]=A('<h1 id="reinforce-与方差" tabindex="-1">REINFORCE 与方差 <a class="header-anchor" href="#reinforce-与方差" aria-label="Permalink to &quot;REINFORCE 与方差&quot;">​</a></h1><div class="epigraph"><p>REINFORCE 便宜、无偏、不需要任何模型点头；代价是用整条轨迹的命运，为一小步参数更新作证。</p><footer>—— 据 Williams, 1992；Sutton &amp; Barto, Reinforcement Learning, 2018 §13.3 整理</footer></div><p><a href="/llm/policy-gradient-theorem">上一课</a>把 \\(\\nabla_\\theta J\\) 写成得分函数乘回报的期望，并说明转移核为何整段消失。定理只保证无偏，没保证好用：把期望换成一次采样，估计量的方差可能大到把方向淹没。本课写这条定理的最直接实现 REINFORCE——整条回合采完、按回报加权更新一次；方差从哪里来（长回合、回报尺度、信用分配），以及不引入新估计量时能做哪些经验减缩。成体系的减法——基线与优势——留给下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>REINFORCE 的更新是：采一整条回合，对每步算 \\(g_t=G_t\\,\\nabla_\\theta\\log\\pi_\\theta(a_t\\mid s_t)\\)，求和更新一次。无偏，但方差有三处来源。其一，\\(G_t\\) 是从 \\(t\\) 到回合末的随机和：回合越长，求和的项数越多，波动越大；语言模型的思维链几百个 token 共享一个终端奖励，等于用一次抛硬币监督几百个决策。其二，回报尺度直接进梯度：奖励从 \\(\\{0,1\\}\\) 换成 \\(\\{0,100\\}\\)，等效学习率放大百倍，调好的步长随之作废。其三，信用分配：一个标量乘整段对数概率，对的前缀和错的后缀一起被赏罚，梯度里混进与「该步好坏」无关的噪声。</p><p><span class="marginnote">「用一次抛硬币监督几百个决策」可以算得更具体：思维链 500 token、终端奖励 0/1。一次更新里这 500 步的梯度全被同一个 0 或 1 乘——奖励 1 时全体受赏（含中途写错的部分），0 时全体受罚（含推对的部分）。「每一步各自该得几分」的信息完全没进来。</span></p><p>不这么做会错在哪：只看平均回报不看梯度方差去调学习率与批大小，会得到「有时收敛有时发散」且换一天就复现不了的结果——噪声才是这条方法的主参数。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>经验减缩有四件先做。批内标准化：对一批 rollout 的回报减均值、除标准差后再加权——这是下一课基线思想的批量预演，零成本。Token 平均还是 token 求和要钉死：求和时同样的优势被长序列放大，训练会向长答案漂移。多样本平均：同一 \\(\\theta\\) 下采 \\(N\\) 条轨迹取均值，标准差降 \\(\\sqrt{N}\\) 倍，成本线性涨。最后是梯度裁剪：把梯度范数截到上限以下。工程止血，但它改的是估计量本身——有偏，报告里应当承认。</p><p><span class="marginnote">\\(\\sqrt{N}\\) 这个规律值得记牢：标准差要降 10 倍，样本得采 100 条；降 100 倍就要 10000 条。堆样本压方差贵得离谱——这就是为什么这条路线迟早要走到基线与优势函数：靠结构省方差，而不是靠流量。</span></p>',10)),(t(),i(B,null,{default:e(()=>[n(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20EP%5B%22%E6%95%B4%E6%9D%A1%E5%9B%9E%E5%90%88%E9%87%87%E5%AE%8C%22%5D%20--%3E%20R%5B%22%E7%BB%88%E7%AB%AF%E5%A5%96%E5%8A%B1%EF%BC%88%E7%A8%80%E7%96%8F%EF%BC%89%22%5D%0A%20%20R%20--%3E%20GT%5B%22%E9%80%90%E6%AD%A5%E6%8A%98%E6%89%A3%E5%9B%9E%E6%8A%A5%20Gt%22%5D%0A%20%20GT%20--%3E%20G%5B%22%E5%BE%97%E5%88%86%E4%B9%98%20Gt%20%E6%B1%82%E5%92%8C%22%5D%0A%20%20G%20--%3E%20NORM%5B%22%E6%89%B9%E5%86%85%E6%A0%87%E5%87%86%E5%8C%96%EF%BC%88%E5%8F%AF%E9%80%89%EF%BC%89%22%5D%0A%20%20NORM%20--%3E%20UP%5B%22%E4%B8%80%E5%9B%9E%E5%90%88%E4%B8%80%E6%AC%A1%E6%9B%B4%E6%96%B0%22%5D%0A%20%20UP%20--%3E%20NEXT%5B%22%E6%96%B0%E7%AD%96%E7%95%A5%E9%87%8D%E6%96%B0%E9%87%87%E6%A0%B7%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[r(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,[a("span",{class:"marginnote"},"二值奖励、成功率 0.2 时，64 条 rollout 里期望只有约 13 条带正信号；若整批全 0 且权重就是 \\(G_t\\) 本身，梯度恰为零——不是学稳了，而是这批没有信号。全对批则反向：一切样本都被推高，方差全靠参考正则去收。")],-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[r("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,"把方差写成两项看得更清楚：\\(\\mathrm{Var}[\\hat g]=\\mathbb{E}[G_t^2\\lVert\\nabla_\\theta\\log\\pi_\\theta(a_t\\mid s_t)\\rVert^2]-\\lVert\\nabla_\\theta J\\rVert^2\\)。无偏性只照顾第二项（估计对准期望），第一项——回报波动与得分范数的耦合——原封不动。得分范数随序列长度增长：对数概率是几百项的和，同等回报下长序列的梯度天然更吵。这也解释了为什么 REINFORCE 每回合只更新一次：回合没结束 \\(G_t\\) 未定义，蒙特卡洛把「无偏」换成了「必须等剧终」，而长回合与稀疏终端奖励把这笔交换变得昂贵。",-1)),(t(),i(B,null,{default:e(()=>[n(l,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20V%5B%22%E4%BC%B0%E8%AE%A1%E9%87%8F%E6%96%B9%E5%B7%AE%E7%9A%84%E4%B8%A4%E9%A1%B9%E5%88%86%E8%A7%A3%22%5D%20--%3E%20T1%5B%22%E7%AC%AC%E4%B8%80%E9%A1%B9%3A%20E%5BG_t%20%E6%96%B9%E5%B7%AE%20x%20%E5%BE%97%E5%88%86%E8%8C%83%E6%95%B0%E5%B9%B3%E6%96%B9%5D%22%5D%0A%20%20V%20--%3E%20T2%5B%22%E7%AC%AC%E4%BA%8C%E9%A1%B9%3A%20%E7%9C%9F%E5%AE%9E%E6%A2%AF%E5%BA%A6%E8%8C%83%E6%95%B0%E5%B9%B3%E6%96%B9%2C%20%E6%97%A0%E5%81%8F%E6%80%A7%E4%BF%9D%E8%AF%81%E5%AE%83%22%5D%0A%20%20T1%20--%3E%20S1%5B%22%E5%9B%9E%E6%8A%A5%E6%B3%A2%E5%8A%A8%3A%20G_t%20%E9%9A%8F%E7%BB%88%E7%AB%AF%E5%A5%96%E5%8A%B1%E5%89%A7%E7%83%88%E6%8A%96%E5%8A%A8%22%5D%0A%20%20T1%20--%3E%20S2%5B%22%E5%BE%97%E5%88%86%E8%8C%83%E6%95%B0%3A%20%E5%BA%8F%E5%88%97%E8%B6%8A%E9%95%BF%2C%20%E5%AF%B9%E6%95%B0%E6%A6%82%E7%8E%87%E5%92%8C%E8%B6%8A%E5%A4%A7%22%5D%0A%20%20S1%20--%3E%20COUP%5B%22%E4%B8%A4%E8%80%85%E7%9B%B8%E4%B9%98%3A%20%E9%95%BF%E5%BA%8F%E5%88%97%E9%81%87%E7%A8%80%E7%96%8F%E5%A5%96%E5%8A%B1%E6%9C%80%E5%90%B5%22%5D%0A%20%20S2%20--%3E%20COUP%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[r(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=A('<p><span class="marginnote">常见误区：把「无偏」当成「可信」。无偏只承诺平均而言方向对，不保证单次更新可用——方差大到一定程度，单次梯度与真实方向可能几乎不相关。所以工程上宁可接受梯度裁剪带来的小偏差，也要先让训练曲线跑得起来。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>无偏性依赖数据来自当前策略：复用旧轨迹要重要性加权，而比率方差随回合长度爆炸，<a href="/llm/truncated-importance-sampling">截断重要性采样</a>是那条线上的工程答案。梯度裁剪、早停这类操作都让估计有偏，收益是能跑通；「理论纯度」在这里不是美德，但要记账。评估时应报告梯度范数与回报分布，不只报平均分。基线能把上面第一项压下来多少、代价是什么，是下一课的主题。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>REINFORCE = 策略梯度定理的蒙特卡洛实现：回合更新、按回报加权得分。</li><li>方差三源：回合长度、回报尺度、单标量信用分配；得分范数随序列长度增长。</li><li>经验减缩：批内标准化、token 平均约定、多样本平均、梯度裁剪（有偏）。</li><li>全零批次权重为零时学习静默停摆，监控要看得见这件事。</li><li>复用旧数据必须处理重要性比率，其方差随回合长度爆炸。</li><li>出处：Williams, 1992；Sutton &amp; Barto, 2018，§13.3。</li></ul>',5))])}const D=o(p,[["render",m]]);export{u as __pageData,D as default};
